    let first = unsafe { first_level.get_unchecked(first_index) };
    let first_bits = first.bits;
    let first_value = first.value;

    if first_bits as c_uint > HUFFMAN_TABLE_BITS {
        let nbits: uint64_t =
            (first_bits as c_uint).wrapping_sub(HUFFMAN_TABLE_BITS) as uint64_t;
        BrotliDropBits(br, HUFFMAN_TABLE_BITS as uint64_t);
        let second_index = (first_value as uint64_t)
            .wrapping_add(bits >> 8 as c_uint & BitMask(nbits))
            as usize;
        // SAFETY: the second-level table is addressed from the original base
        // pointer exactly as in `table = table.offset(...)`; the decoder's
        // table layout guarantees this computed entry exists, and no mutable/
        // reference aliasing is introduced.
        let second_level = unsafe { core::slice::from_raw_parts(table, second_index + 1) };
        // SAFETY: `second_level` was created with length `second_index + 1`.
        let final_entry = unsafe { second_level.get_unchecked(second_index) };
        let final_bits = final_entry.bits;
        let final_value = final_entry.value;
        BrotliDropBits(br, final_bits as uint64_t);
        final_value as uint64_t
    } else {
        BrotliDropBits(br, first_bits as uint64_t);
